 'use strict';
function setupTutorial(){run.tutorial={walk:false,jump:false,climb:false,interact:false,attack:false,startX:110};platforms=[{x:0,y:420,w:1200},{x:150,y:300,w:280}];ladders=[{x:210,top:300,bottom:420}];interactables=[{kind:'training',x:350,y:300,radius:48,action:()=>{tutorialMark('interact');toast('โต้ตอบสำเร็จ · ลงไปฝึกโจมตีด้วย C')}}];monsters=monsters.slice(0,3);monsters.forEach((m,i)=>{m.x=m.home=500+i*100;m.y=420;m.low=470+i*100;m.high=550+i*100;m.p=0});player.x=110;player.y=420;resetMotion();renderTutorialHint()}
function tutorialMark(key){if(!run?.tutorial||run.finished||run.tutorial[key])return;run.tutorial[key]=true;renderTutorialHint()}
function updateTutorial(){const t=run?.tutorial;if(!t){const hint=document.getElementById('tutorialHint');if(hint)hint.hidden=true;return}if(Math.abs(player.x-t.startX)>=60)tutorialMark('walk');if(player.climbing)tutorialMark('climb');renderTutorialHint()}
function renderTutorialHint(){let hint=document.getElementById('tutorialHint');if(!hint){hint=document.createElement('div');hint.id='tutorialHint';hint.setAttribute('role','status');document.querySelector('.playfield').append(hint)}const t=run?.tutorial;hint.hidden=!t||run.finished;if(!t)return;hint.replaceChildren();const tasks=[['walk','← → เดิน'],['jump','Spacebar กระโดด'],['climb','↑ ↓ ปีนบันไดที่อยู่ด้านหน้า'],['interact','Spacebar โต้ตอบป้ายบนแพลตฟอร์ม'],['attack','C โจมตีมอนสเตอร์ด้านล่าง']];for(const [id,text]of tasks){const row=document.createElement('div');row.textContent=(t[id]?'✓ ':'□ ')+text;row.classList.toggle('done',!!t[id]);hint.append(row)}if(tasks.every(([id])=>t[id])){const done=document.createElement('strong');done.textContent='ฝึกครบแล้ว · Esc → จบรอบ เพื่อกลับหมู่บ้าน';hint.append(done)}}
function drawTutorialSign(){const x=350,y=300;rect(x-3,y-50,6,50,'#785b3e');rect(x-42,y-68,84,27,'#264734');ctx.font='12px Thai,Tahoma';ctx.textAlign='center';ctx.fillStyle='#f3dc9e';ctx.fillText('Spacebar โต้ตอบ',x,y-49)}
